import { Routes } from "@angular/router";
import { ClassRoutine } from "./class-routine/class-routine";
import { ClassRoutineAdd } from "./class-routine/class-routine-add/class-routine-add";
import { Classz } from "./classz/classz";
import { ClasszAdd } from "./classz/classz-add/classz-add";
import { Institute } from "./institute/institute";
import { InstituteAdd } from "./institute/institute-add/institute-add";
import { StudentPromote } from "./student-promote/student-promote";
import { StudentPromoteAdd } from "./student-promote/student-promote-add/student-promote-add";
import { Sectionz } from "./sectionz/sectionz";
import { SectionzAdd } from "./sectionz/sectionz-add/sectionz-add";
import { RoutezFeatureModule } from "@_core/_route";
import { ClassSection } from "./class-section/class-section";
import { ClassSectionAdd } from "./class-section/class-section-add/class-section-add";

export const Routez: Routes = new RoutezFeatureModule(
  ['Education', 'Attendance'],
  'feature/edu'
)
.feature(
  Institute,
  InstituteAdd,
  'institute',
  'Institute'
)
.feature(
  Classz,
  ClasszAdd,
  'class',
  'Class'
)
.feature(
  Sectionz,
  SectionzAdd,
  'section',
  'Section'
)
.feature(
  ClassSection,
  ClassSectionAdd,
  'class-section',
  'Class Section'
)
.feature(
  ClassRoutine,
  ClassRoutineAdd,
  'class-routine',
  'Class Routine'
)
.feature(
  StudentPromote,
  StudentPromoteAdd,
  'student-promote',
  'Student Promote'
)
.build();
