import { BaseClassTemplate } from '@_core/__base';
import { URL_CONTRL, URL_SRVC } from '@_core/_client';
import { TM_List } from '@_core/_pagination';
import {
  ChangeDetectionStrategy,
  Component,
  OnInit,
  ViewEncapsulation,
} from '@angular/core';

@Component({
  standalone: false,
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  selector: 'aam-classz',
  templateUrl: './class-section.html',
})
export class ClassSection extends BaseClassTemplate implements OnInit {
  ngOnInit() {
    this.initTables();
  }
  initTables() {
    this._template.lb = new TM_List(this,
      {
        srvc: URL_SRVC.Edu,
        cntrl: URL_CONTRL.Edu.Classz, // Classz,
      },
      [
        { key: 'class', name: 'Class'},
        { key: 'section', name: 'Section'},
        { key: 'teacher', name: 'Teacher'},
        { key: 'gender', name: 'Gender'},
        { key: 'timeFrom', name: 'Time From'},
        { key: 'timeTo', name: 'Time To'},
        { key: 'studentTotal', name: 'Total Students'},
      ]
    ).init();
  }
}
