import { BaseClassSrvc } from "@_core/__base";
import { FormBase } from "@_core/_form";

export function MyForm(that: BaseClassSrvc, d: any = {}) {
  that._fs._form = that._fb.group({
    ...FormBase(that, d),
    contact: [d?.contact || '', that._vs._val('Contact')],
    email: [d?.email || '', that._vs._val('', { maxChar: 50, email: 1, specialChar: 0 })],
    branch: [d?.branch || '', that._vs._val('Branch')],
    address: [d?.address || '', that._vs._val('Address')],
    location: [d?.location || ''],
    image: [d?.image || ''],
  });
}
